module traffic_light_controller #(parameter GREEN_CYCLES=10,YELLOW_CYCLES=3)(input wire clk,rst_n,output reg [2:0] road_a,road_b); localparam A_GREEN=0,A_YELLOW=1,B_GREEN=2,B_YELLOW=3; reg [1:0] state; reg [31:0] timer; always @(posedge clk or negedge rst_n) begin if(!rst_n)begin state<=A_GREEN;timer<=0;end else begin timer<=timer+1'b1;case(state) A_GREEN:if(timer>=GREEN_CYCLES-1)begin state<=A_YELLOW;timer<=0;end A_YELLOW:if(timer>=YELLOW_CYCLES-1)begin state<=B_GREEN;timer<=0;end B_GREEN:if(timer>=GREEN_CYCLES-1)begin state<=B_YELLOW;timer<=0;end B_YELLOW:if(timer>=YELLOW_CYCLES-1)begin state<=A_GREEN;timer<=0;end default:begin state<=A_GREEN;timer<=0;end endcase end end always @* begin road_a=3'b100;road_b=3'b100;case(state) A_GREEN:begin road_a=3'b001;road_b=3'b100;end A_YELLOW:begin road_a=3'b010;road_b=3'b100;end B_GREEN:begin road_a=3'b100;road_b=3'b001;end B_YELLOW:begin road_a=3'b100;road_b=3'b010;end endcase end endmodule
